contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 seed) public {
        // Admissible domain: any bytes4 value; use the fuzzed seed to derive one.
        bytes4 queried = bytes4(uint32(uint256(seed)));
        // General rule: C always advertises the ERC1155 Metadata URI interface
        // (its supportsInterface must return true for IERC1155MetadataURI.interfaceId,
        // regardless of any other input). The mutant removed that disjunct.
        assertTrue(c.supportsInterface(type(IERC1155MetadataURI).interfaceId));
        // queried participates only as fuzz input; the invariant above must hold for all inputs
        // but the buggy version returns false for the Metadata URI id and will fail the assertion.
    }
}

