pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 constant IERC165_ID = 0x01ffc9a7;

    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(uint256 seed) public {
        bytes4 iid = bytes4(uint32(seed));
        // Rule: whenever the queried id is the ERC-165 interface id itself,
        // supportsInterface must return true (ERC-165 reflexivity).
        // The mutant removed the super.supportsInterface disjunct, so it
        // returns false for 0x01ffc9a7.
        bool ok = true;
        if (iid == IERC165_ID) {
            ok = c.supportsInterface(iid);
        }
        assertTrue(ok || iid != IERC165_ID, "ERC-165 id must be supported");
    }
}

