pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account, uint256 id) public {
        // Admissible domain: any account, any id (as owner) — wide domain.
        // General rule: balanceOf completes (does not revert) for any account;
        // but for the zero address it MUST revert. Equivalently:
        // for every (account, id), the call succeeds iff account != address(0).
        bool ok;
        uint256 bal;
        try c.balanceOf(account, id) returns (uint256 b) {
            ok = true;
            bal = b;
        } catch {
            ok = false;
        }

        // Single assertion: the call's completion status must match admissibility,
        // and when it completes for a non-zero account it must not be an
        // undefined zero-address read (zero address is rejected, never queried).
        assertTrue(
            (account == address(0)) ? !ok : (ok && bal == c.balanceOf(account, id)),
            "balanceOf must revert for the zero address and succeed otherwise"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(uint256 seed, uint256 id) public {
        // Keep the domain wide: half of the space maps to the zero address so the
        // fuzzer reliably exercises the boundary case, the other half is arbitrary.
        address account = (seed % 2 == 0) ? address(0) : address(uint160(seed));

        // Rule: for any (account, id), a completed balanceOf call must never be
        // paired with the zero address; the zero-address query must revert.
        bool ok;
        uint256 bal;
        try c.balanceOf(account, id) returns (uint256 b) {
            ok = true;
            bal = b;
        } catch {
            ok = false;
        }

        assertTrue(!(ok && account == address(0)) && (!ok || bal >= 0), "balanceOf must revert for zero address");
    }
}

