// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    FakeNeuron nrn;

    function setUp() public {
        c = new C(address(this), address(this));
        nrn = new FakeNeuron();
        c.instantiateNeuronContract(address(nrn));
    }

    function testFuzz_property(uint256 tokenId, uint16 dailyAllowance, uint256 quantity, address actor) public {
        vm.assume(actor != address(0));
        uint16 d = uint16(bound(dailyAllowance, 1, 65535));
        // create exactly one game item (admin == address(this)), non-finite, price 0, transferable false
        c.createGameItem("item", "uri", false, false, 0, 0, d);
        tokenId = bound(tokenId, 0, c.uniqueTokensOutstanding() - 1);
        quantity = bound(quantity, 1, d);

        vm.prank(actor);
        c.mint(tokenId, quantity);

        assertTrue(c.balanceOf(actor, tokenId) == quantity);
    }
}

contract FakeNeuron {
    function balanceOf(address) external pure returns (uint256) {
        return type(uint256).max;
    }

    function approveSpender(address, uint256) external pure {}

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
